import { describe, expect, it } from "vitest";
import golden from "./__fixtures__/compact-golden.json";
import { expandResult, isCompact, wireOf, type CompactResult } from "./compact";

// The fixture is generated by the Python engine (backend/tests/make_compact_fixture.py) and kept fresh
// by a backend test: `full` is what the engine recorded, `compact` is what the API sends.
const cases = (golden as { cases: { name: string; full: unknown; compact: unknown }[] }).cases;

describe("compact result decoder", () => {
  it("has a non-trivial fixture", () => {
    expect(cases.length).toBeGreaterThanOrEqual(4);
  });

  for (const c of cases) {
    it(`reproduces the engine's full result exactly: ${c.name}`, () => {
      expect(isCompact(c.compact)).toBe(true);
      const decoded = expandResult(c.compact as CompactResult);
      expect(decoded).toEqual(c.full);
    });
  }

  it("restores every recorded frame when stepping from the last to the first", () => {
    const c = cases.find((x) => x.name === "mlfq-io-boost-cost1")!;
    const decoded = expandResult(c.compact as CompactResult);
    const full = (c.full as { frames: unknown[] }).frames;
    expect(full.length).toBeGreaterThan(10);
    for (let i = full.length - 1; i >= 0; i--) expect(decoded.frames[i]).toEqual(full[i]);
  });

  it("keeps the wire object for compact JSON export", () => {
    const wire = cases[0].compact as CompactResult;
    expect(wireOf(expandResult(wire))).toBe(wire);
  });

  it("rejects unrelated objects", () => {
    expect(isCompact({ format: "something-else" })).toBe(false);
    expect(isCompact(null)).toBe(false);
  });
});
